    {"claim": "CVE coordination shares vulnerability detail with verified defenders before any public release—the model for sharing hazard data without arming attackers already exists.", "targets": [], "relationship": ""},
    {"claim": "Optional transparency selects against rigor, because a published red-team failure is a market liability and the lab that skips the evaluation ships first.", "targets": [], "relationship": ""},
    {"claim": "Concentrating oversight authority creates its own failure modes—capture and incumbent lock-in—so the recipient must be bound by named liability, access verification, and real authority to stop a launch.", "targets": [], "relationship": ""}
  ]
